shader_type canvas_item;
// CRT post-pass (curvature, phosphor mask, vignette, chroma) — stacks above noir + scanline.
// Edge-aware RGB offset: luminance edges (white sprites) + red-ink fringe (noir line art).

uniform sampler2D screen_texture : hint_screen_texture, repeat_disable, filter_nearest;
uniform float curvature : hint_range(0.0, 0.25) = 0.08;
uniform float scanline_strength : hint_range(0.0, 0.5) = 0.12;
uniform float mask_strength : hint_range(0.0, 1.0) = 0.35;
uniform float vignette : hint_range(0.0, 1.0) = 0.22;
uniform float chroma : hint_range(0.0, 0.01) = 0.0025;
uniform float outline_edge_threshold : hint_range(0.0, 1.0) = 0.12;
uniform float outline_edge_strength : hint_range(0.0, 3.0) = 1.0;
uniform float outline_rgb_offset : hint_range(0.0, 0.03) = 0.006;
uniform float outline_softness : hint_range(0.0, 0.25) = 0.08;
uniform float outline_ink_fringe : hint_range(0.0, 1.5) = 0.85;

vec2 curve_uv(vec2 uv, float amount) {
	vec2 c = uv - 0.5;
	float r2 = dot(c, c);
	return uv + c * r2 * amount;
}

float sample_lum(vec2 uv) {
	return dot(texture(screen_texture, uv).rgb, vec3(0.299, 0.587, 0.114));
}

float red_ink_amount(vec3 rgb) {
	float red_dom = rgb.r - max(rgb.g, rgb.b);
	return smoothstep(0.06, 0.28, red_dom);
}

float rgb_edge_strength(vec2 uv) {
	vec2 px = 1.0 / vec2(textureSize(screen_texture, 0));
	vec3 c = texture(screen_texture, uv).rgb;
	float edge = 0.0;
	edge += length(texture(screen_texture, uv + vec2(px.x, 0.0)).rgb - texture(screen_texture, uv - vec2(px.x, 0.0)).rgb);
	edge += length(texture(screen_texture, uv + vec2(0.0, px.y)).rgb - texture(screen_texture, uv - vec2(0.0, px.y)).rgb);
	edge += abs(red_ink_amount(c) - red_ink_amount(texture(screen_texture, uv + px).rgb)) * 2.0;
	edge += abs(red_ink_amount(c) - red_ink_amount(texture(screen_texture, uv - px).rgb)) * 2.0;
	float lum_edge = 0.0;
	lum_edge += abs(sample_lum(uv + vec2(px.x, 0.0)) - sample_lum(uv - vec2(px.x, 0.0)));
	lum_edge += abs(sample_lum(uv + vec2(0.0, px.y)) - sample_lum(uv - vec2(0.0, px.y)));
	return max(edge, lum_edge);
}

float outline_edge_mask(vec2 uv) {
	float edge = rgb_edge_strength(uv);
	float lo = outline_edge_threshold - outline_softness;
	float hi = outline_edge_threshold + outline_softness;
	return smoothstep(lo, hi, edge) * outline_edge_strength;
}

// Noir line art is pure red — channel offsets alone cannot fringe it; bleed ink into G/B.
vec3 apply_red_ink_fringe(vec2 uv, vec3 col, float off) {
	float ink = red_ink_amount(texture(screen_texture, uv).rgb);
	if (ink < 0.02) {
		return col;
	}
	float ink_l = texture(screen_texture, uv + vec2(off, 0.0)).r;
	float ink_r = texture(screen_texture, uv - vec2(off, 0.0)).r;
	float ink_c = texture(screen_texture, uv).r;
	float fringe = ink * outline_ink_fringe;
	col.r = max(col.r, max(ink_l, ink_c, ink_r));
	col.g = max(col.g, max(ink_l, ink_c) * fringe * 0.42);
	col.b = max(col.b, max(ink_r, ink_c) * fringe * 0.48);
	return col;
}

void fragment() {
	vec2 uv = curve_uv(SCREEN_UV, curvature);
	vec3 col = vec3(0.0);
	if (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) {
		float edge_boost = outline_edge_mask(uv);
		float ink = red_ink_amount(texture(screen_texture, uv).rgb);
		float off = chroma + outline_rgb_offset * max(edge_boost, ink * 0.85);
		col.r = texture(screen_texture, uv + vec2(off, 0.0)).r;
		col.g = texture(screen_texture, uv).g;
		col.b = texture(screen_texture, uv - vec2(off, 0.0)).b;
		col = apply_red_ink_fringe(uv, col, off);
		float scan = sin(uv.y * 800.0) * 0.5 + 0.5;
		col *= 1.0 - scan * scanline_strength;
		float mask = sin(uv.x * 900.0) * 0.5 + 0.5;
		col = mix(col, col * 0.85, mask * mask_strength);
		vec2 d = uv - 0.5;
		float vig = 1.0 - dot(d, d) * vignette * 4.0;
		col *= vig;
	}
	COLOR = vec4(col, 1.0);
}

